// ResolveCheckpointRemoteURL resolves the checkpoint remote URL from settings.
// Returns the URL and true if a checkpoint_remote is configured, or ("", false) otherwise.
// This is used by the resume command to fetch metadata from the checkpoint remote.
func ResolveCheckpointRemoteURL(ctx context.Context) (string, bool) {
	s, err := settings.Load(ctx)
	if err != nil {
		return "", false
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return "", false
	}

	// Get the push remote URL for protocol detection
	pushRemoteURL, err := getRemoteURL(ctx, "origin")
	if err != nil {
		return "", false
	}

	pushInfo, err := parseGitRemoteURL(pushRemoteURL)
	if err != nil {
		return "", false
	}

	checkpointURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
	if err != nil {
		return "", false
	}

	return checkpointURL, true
}

// fetchMetadataBranchIfMissing fetches the metadata branch from a URL only if it doesn't exist locally.

// FetchMetadataFromCheckpointRemote fetches the entire/checkpoints/v1 branch from the
// configured checkpoint_remote URL and updates the local branch.
// This is used when checkpoints are stored in a separate repo (e.g., entireio/cli-checkpoints)
// and the local metadata branch is missing or stale.
// Returns an error if the fetch fails or no checkpoint_remote is configured.
func FetchMetadataFromCheckpointRemote(ctx context.Context) error {
	checkpointURL, ok := strategy.ResolveCheckpointRemoteURL(ctx)
	if !ok {
		return errors.New("no checkpoint_remote configured")
	}

	branchName := paths.MetadataBranchName

	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Fetch to a temp ref to avoid polluting the remote-tracking namespace.
	tmpRef := "refs/entire-fetch-tmp/" + branchName
	refSpec := fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
	fetchCmd := exec.CommandContext(ctx, "git", "fetch", "--no-tags", checkpointURL, refSpec)
	fetchCmd.Stdin = nil
	fetchCmd.Env = append(os.Environ(),
		"GIT_TERMINAL_PROMPT=0",
	)
	if output, err := fetchCmd.CombinedOutput(); err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return errors.New("checkpoint remote fetch timed out after 2 minutes")
		}
		return fmt.Errorf("failed to fetch %s from checkpoint remote: %s: %w", branchName, strings.TrimSpace(string(output)), err)
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	// Get the fetched ref
	fetchedRef, err := repo.Reference(plumbing.ReferenceName(tmpRef), true)
	if err != nil {
		return fmt.Errorf("branch '%s' not found after fetch from checkpoint remote: %w", branchName, err)
	}

	// Create or update local branch pointing to the fetched commit
	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), fetchedRef.Hash())
	if err := repo.Storer.SetReference(localRef); err != nil {
		return fmt.Errorf("failed to create local %s branch: %w", branchName, err)
	}

	// Clean up the temp ref (best-effort)
	_ = repo.Storer.RemoveReference(plumbing.ReferenceName(tmpRef)) //nolint:errcheck // cleanup is best-effort

	return nil
}

