func tryReadCheckpointFromTree(ctx context.Context, tree *object.Tree, treeErr error, repoForBlobs *git.Repository, checkpointID id.CheckpointID) (*strategy.CheckpointInfo, error) {
	if treeErr != nil {
		return nil, treeErr
	}
	cpSubtree, cpErr := tree.Tree(checkpointID.Path())
	if cpErr != nil {
		return nil, cpErr
	}
	ft := checkpoint.NewFetchingTree(ctx, cpSubtree, repoForBlobs.Storer, FetchBlobsByHash)
	if _, pfErr := ft.PreFetch(); pfErr != nil {
		logging.Debug(ctx, "tryReadCheckpointFromTree: PreFetch failed",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", pfErr.Error()),
		)
	}
	return strategy.ReadCheckpointMetadataFromSubtree(ft, checkpointID.Path())
}

